def locate_cf4():
    """Cache em ./cache; senao copia do release_clean vizinho; senao instrui download."""
    os.makedirs(CACHE, exist_ok=True)
    cached = os.path.join(CACHE, "cf4_flow_canonical.csv")
    if os.path.exists(cached):
        return cached, "cache"
    # vizinho (release_clean do TGL_CODE_ONE_REAL_FALSIFIER)
    cand = os.path.join(BASE, "..", "TGL_CODE_ONE_REAL_FALSIFIER", "release_clean",
                        "data", "flow", "cosmicflows4", "cf4_flow_canonical.csv")
    if os.path.exists(cand):
        shutil.copy(cand, cached)
        return cached, "copied_from_release_clean"
    return None, "absent"


# ============ dados reais: DESIVAST DR1 (Certificado IV) ============
def locate_desivast(allow_download=None):
    """Localiza (ou baixa) os catalogos DESIVAST DR1. INTELIGENTE: (1) cache local
    ./cache/voids/desivast; (2) o release_clean vizinho (onde o fetcher oficial do
    TGL_CODE_ONE_REAL_FALSIFIER os deposita) -- quem JA TEM nao baixa de novo;
    (3) download automatico da fonte publica (data.desi.lbl.gov) por arquivo
    faltante, SGC primeiro (menor). TGL_VOID_NO_NETWORK=1 desliga a rede.
    Retorna {algoritmo: [(path, bytes, origem), ...]} so' com o que EXISTE."""
    if allow_download is None:
        allow_download = os.environ.get("TGL_VOID_NO_NETWORK", "0") != "1"
    roots = [os.path.join(CACHE, "voids", "desivast"),
             os.path.join(BASE, "TGL_CODE_ONE_REAL_FALSIFIER", "release_clean",
                          "data", "voids", "desivast"),
             os.path.join(BASE, "..", "TGL_CODE_ONE_REAL_FALSIFIER", "release_clean",
                          "data", "voids", "desivast")]
    found = {}
    for alg, files in DESIVAST_FILES.items():
        hits = []
        for fname in files:
            got = None
            for root in roots:
                p = os.path.join(root, fname)
                if os.path.exists(p) and os.path.getsize(p) > 1024:
                    got = (p, os.path.getsize(p), "local")
                    break
            if got is None and allow_download:
                dest_dir = roots[0]
                os.makedirs(dest_dir, exist_ok=True)
                dest = os.path.join(dest_dir, fname)
                try:
                    req = urllib.request.Request(DESIVAST_BASE_URL + fname,
                                                 headers={"User-Agent": "um.py-TGL-void-floor"})
                    with urllib.request.urlopen(req, timeout=120) as r, open(dest, "wb") as f:
                        shutil.copyfileobj(r, f, length=1 << 20)
                    if os.path.getsize(dest) > 1024:
                        got = (dest, os.path.getsize(dest), "downloaded")
                except Exception:
                    if os.path.exists(dest):
                        os.remove(dest)
            if got is not None:
                hits.append(got)
        if hits:
            found[alg] = hits
    return found


def acquire_evidence(key, allow_download=None):
    """CADEIA DE CUSTODIA (v139): localiza (ou baixa) UM dado externo registrado em
    EVIDENCE_SOURCES, na subpasta de cache que os modulos ja' leem. Idempotente
    (presente com tamanho esperado => reconhece e PULA, nao rebaixa); fail-closed
    (download com tamanho errado => apaga e tenta o proximo espelho; nada de arquivo
    meio-baixado). TGL_NO_NETWORK=1 (ou o legado TGL_VOID_NO_NETWORK=1) desliga a rede.
    Retorna (path_ou_None, registro_do_ato)."""
    src = EVIDENCE_SOURCES[key]
    if allow_download is None:
        allow_download = (os.environ.get("TGL_NO_NETWORK",
                          os.environ.get("TGL_VOID_NO_NETWORK", "0")) != "1")
    dest_dir = os.path.join(CACHE, *src["cache_subdir"].split("/"))
    os.makedirs(dest_dir, exist_ok=True)
    dest = os.path.join(dest_dir, src["filename"])
    exp_bytes = src.get("bytes")
    rec = {"key": key, "filename": src["filename"], "used_by": src.get("used_by"),
           "source": src.get("source_cite")}
    exp_sha = src.get("sha256")
    _SHA_CHECK_MAX = 256 * 1024 * 1024   # confere sha ate 256 MB no caminho 'present'

    def _sha_ok(path):
        # v142: a proveniencia 'provada por sha' agora E' conferida (fail-closed);
        # None = nao pinado; True/False = conferido; 'skipped_large' = grande demais
        if exp_sha is None:
            return None
        if os.path.getsize(path) > _SHA_CHECK_MAX:
            return "skipped_large"
        return bool(sha_file(path) == exp_sha)
    # idempotente: presente com tamanho esperado E sha pinado conferido
    if os.path.exists(dest) and (exp_bytes is None or os.path.getsize(dest) == exp_bytes):
        sv = _sha_ok(dest)
        if sv is False:
            os.remove(dest)                                   # fail-closed: sha errado
            rec["last_error"] = "sha256 mismatch on present file (removed)"
        else:
            rec.update({"status": "present", "bytes": os.path.getsize(dest),
                        "downloaded": False, "sha256_verified": sv})
            return dest, rec
    if not allow_download:
        rec.update({"status": "absent_no_network", "downloaded": False})
        return None, rec
    for url in src.get("urls", []):
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "um.py-TGL-chain-of-custody"})
            with urllib.request.urlopen(req, timeout=600) as r, open(dest, "wb") as f:
                shutil.copyfileobj(r, f, length=1 << 20)
            got = os.path.getsize(dest)
            if exp_bytes is not None and got != exp_bytes:
                os.remove(dest)                                   # fail-closed: tamanho errado
                rec["last_error"] = "size mismatch (got %d, expected %d)" % (got, exp_bytes)
                continue
            if exp_sha is not None and sha_file(dest) != exp_sha:
                os.remove(dest)                                   # fail-closed: sha errado (v142)
                rec["last_error"] = "sha256 mismatch after download (removed)"
                continue
            rec.update({"status": "downloaded", "bytes": got, "downloaded": True,
                        "url": url, "sha256_verified": (True if exp_sha is not None else None)})
            return dest, rec
        except Exception as e:
            if os.path.exists(dest):
                os.remove(dest)
            rec["last_error"] = repr(e)[:200]
    rec.update({"status": "download_failed", "downloaded": False})
    return None, rec


def build_custody_manifest():
    """A PROVENIENCIA DETERMINISTICA (so' constantes de EVIDENCE_SOURCES, sem tocar disco):
    a lista ordenada {chave, arquivo, subpasta, fonte publica, bytes, sha256, used_by,
    acquisition} que entra no MUNDO selado (forma = conteudo) e vira o livro-razao
    cache/CHAIN_OF_CUSTODY.json. Deterministica => o result_hash e' reproduzivel em
    qualquer maquina que adquira o MESMO dado publico."""
    out = []
    for key in sorted(EVIDENCE_SOURCES):
        s = EVIDENCE_SOURCES[key]
        out.append({"key": key, "filename": s["filename"], "cache_subdir": s["cache_subdir"],
                    "source": s.get("source_cite"), "expected_bytes": s.get("bytes"),
                    "expected_sha256": s.get("sha256"), "used_by": s.get("used_by"),
                    "acquisition": s.get("acquisition")})
    return out


def _sha_file_stream(path):
    """sha256 por streaming (os catalogos chegam a centenas de MB)."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 22), b""):
            h.update(chunk)
    return h.hexdigest()


def _fits_scan_bintables(path, max_rows_load=500000):
    """Leitor FITS minimo em numpy PURO (sem astropy/fitsio; auditavel): varre os HDUs
    por seek (nunca carrega o arquivo inteiro), lista todas as BINTABLEs e materializa
    as colunas so' das tabelas com NAXIS2 <= max_rows_load (os catalogos de vazios sao
    pequenos; tabelas de membership gigantes ficam so' inventariadas). TFORM E/D/J/K/I/A."""
    tables = []
    with open(path, "rb") as f:
        def read_header():
            hdr = {}
            while True:
                block = f.read(2880)
                if len(block) < 2880:
                    return None
                for i in range(0, 2880, 80):
                    card = block[i:i + 80].decode("ascii", errors="replace")
                    key = card[:8].strip()
                    if key == "END":
                        return hdr
                    if card[8:10] == "= ":
                        val = card[10:].split(" /")[0].strip()
                        if val.startswith("'"):
                            hdr[key] = val.strip().strip("'").strip()
                        else:
                            try:
                                hdr[key] = int(val)
                            except ValueError:
                                try:
                                    hdr[key] = float(val)
                                except ValueError:
                                    hdr[key] = val
            # unreachable
        while True:
            hdr = read_header()
            if hdr is None:
                break
            bitpix = abs(int(hdr.get("BITPIX", 8)))
            naxes = [int(hdr.get("NAXIS%d" % k, 0)) for k in range(1, int(hdr.get("NAXIS", 0)) + 1)]
            nbytes = (bitpix // 8) * (int(np.prod(naxes)) if naxes else 0)
            nbytes += int(hdr.get("PCOUNT", 0))
            padded = ((nbytes + 2879) // 2880) * 2880
            xt = str(hdr.get("XTENSION", "")).strip()
            if xt == "BINTABLE":
                n1, n2 = int(hdr.get("NAXIS1", 0)), int(hdr.get("NAXIS2", 0))
                name = str(hdr.get("EXTNAME", "?")).strip()
                nf = int(hdr.get("TFIELDS", 0))
                colnames = [str(hdr.get("TTYPE%d" % k, "col%d" % k)).strip() for k in range(1, nf + 1)]
                entry = {"name": name, "rows": n2, "fields": nf, "colnames": colnames, "cols": None}
                if 0 < n2 <= max_rows_load and n1 * n2 > 0:
                    raw = f.read(n1 * n2)
                    f.seek(padded - n1 * n2, 1)
                    arr = np.frombuffer(raw, dtype=np.uint8).reshape(n2, n1)
                    fmt = {"E": (">f4", 4), "D": (">f8", 8), "J": (">i4", 4),
                           "K": (">i8", 8), "I": (">i2", 2), "B": ("u1", 1), "L": ("u1", 1)}
                    cols, off, parse_ok = {}, 0, True
                    for k in range(1, nf + 1):
                        tform = str(hdr.get("TFORM%d" % k, "")).strip()
                        j = 0
                        while j < len(tform) and tform[j].isdigit():
                            j += 1
                        rep = int(tform[:j]) if j else 1
                        code = tform[j] if j < len(tform) else "?"
                        cname = colnames[k - 1]
                        if code == "A":
                            cols[cname] = None
                            off += rep
                        elif code in fmt:
                            dt, w = fmt[code]
                            sub = arr[:, off:off + rep * w].tobytes()
                            v = np.frombuffer(sub, dtype=dt)
                            cols[cname] = (v.reshape(n2, rep) if rep > 1 else v).astype(float)
                            off += rep * w
                        else:
                            # TFORM nao suportado (P/Q/C/M): offsets ficariam errados --
                            # aborta a materializacao DESTA tabela (fail-closed), mantem inventario
                            parse_ok = False
                            break
                    entry["cols"] = cols if parse_ok else None
                    if not parse_ok:
                        entry["note"] = "TFORM_UNSUPPORTED_MATERIALIZATION_SKIPPED"
                else:
                    f.seek(padded, 1)
                tables.append(entry)
            else:
                f.seek(padded, 1)
    return tables


def cf4_rstruct():
    """R_struct do Grande Atrator a partir de POSICOES (ra/dec/dist). Velocidades IGNORADAS."""
    path, origin = locate_cf4()
    if path is None:
        return {"ok": False, "reason": "CF4 catalogue absent; place cf4_flow_canonical.csv in ./cache "
                "or beside release_clean. Source: %s" % CF4_URL}
    raw = open(path, "rb").read()
    rows = list(csv.DictReader(raw.decode("utf-8").splitlines()))
    ra = np.array([float(r["ra"]) for r in rows]); dec = np.array([float(r["dec"]) for r in rows])
    dist = np.array([float(r["dist_mpc"]) for r in rows])
    w = PREREG_WINDOW
    cra, cdec = math.radians(w["GA_center_RA_deg"]), math.radians(w["GA_center_Dec_deg"])
    chat = np.array([math.cos(cdec) * math.cos(cra), math.cos(cdec) * math.sin(cra), math.sin(cdec)])
    gr, gd = np.radians(ra), np.radians(dec)
    ghat = np.column_stack([np.cos(gd) * np.cos(gr), np.cos(gd) * np.sin(gr), np.sin(gd)])
    pos = ghat * dist[:, None]
    ang = np.degrees(np.arccos(np.clip(ghat @ chat, -1, 1)))
    lo, hi = w["dist_shell_Mpc"]
    sel = (ang <= w["sky_cone_half_angle_deg"]) & (dist >= lo) & (dist <= hi)
    pts = pos[sel]; n_sel = int(sel.sum())
    if n_sel < 20:
        return {"ok": False, "reason": "too few galaxies in pre-registered window (%d)" % n_sel}
    c = pts.mean(axis=0); r = np.linalg.norm(pts - c, axis=1)
    desc = {"n_total": len(rows), "n_selected": n_sel, "centroid": c.tolist()}
    return {"ok": True, "R_struct_Mpc": float(np.percentile(r, 90)),
            "method": w["R_struct_method"], "origin": origin,
            "extent_stats_Mpc": {"p90": float(np.percentile(r, 90)), "p95": float(np.percentile(r, 95)),
                                 "rms": float(np.sqrt(np.mean(r ** 2))), "max": float(r.max())},
            "n_selected": n_sel, "n_total": len(rows),
            "catalog_hash": sha_obj({"sha": hashlib.sha256(raw).hexdigest()}),
            "window_hash": sha_obj(w), "selection_hash": sha_obj(desc), "window": w,
            "caveat": ("R_struct de catalogo de POSICOES limitado em fluxo, com janela declarada, e' "
                       "dependente da selecao (geometria pura). Reportado como cross-check independente; "
                       "a extensao de literatura (Lynden-Bell) e' a linha de base.")}


def cf4_sensitivity(beta):
    """Varredura pre-registrada do Modo B: varia cone, shell, percentil e centro; recomputa
    R_struct e M_GA em cada combinacao; reporta se M permanece na banda cosmologica."""
    path, origin = locate_cf4()
    if path is None:
        return {"ok": False, "reason": "CF4 absent"}
    raw = open(path, "rb").read()
    rows = list(csv.DictReader(raw.decode("utf-8").splitlines()))
    ra = np.radians(np.array([float(r["ra"]) for r in rows]))
    dec = np.radians(np.array([float(r["dec"]) for r in rows]))
    dist = np.array([float(r["dist_mpc"]) for r in rows])
    ghat = np.column_stack([np.cos(dec) * np.cos(ra), np.cos(dec) * np.sin(ra), np.sin(dec)])
    pos = ghat * dist[:, None]
    g = SENSITIVITY_GRID
    lo_band, hi_band = GA_ACCEPTED_WINDOW_Msun
    Ms, n_valid, n_in = [], 0, 0
    for cone in g["cone_half_angle_deg"]:
        for (lo, hi) in g["dist_shell_Mpc"]:
            for pct in g["percentile"]:
                for (dra, ddec) in g["center_offsets_deg"]:
                    cra = math.radians(PREREG_WINDOW["GA_center_RA_deg"] + dra)
                    cdec = math.radians(PREREG_WINDOW["GA_center_Dec_deg"] + ddec)
                    chat = np.array([math.cos(cdec) * math.cos(cra),
                                     math.cos(cdec) * math.sin(cra), math.sin(cdec)])
                    ang = np.degrees(np.arccos(np.clip(ghat @ chat, -1, 1)))
                    sel = (ang <= cone) & (dist >= lo) & (dist <= hi)
                    if int(sel.sum()) < 20:
                        continue
                    pts = pos[sel]; r = np.linalg.norm(pts - pts.mean(axis=0), axis=1)
                    Rs = float(np.percentile(r, pct))
                    M = mass_Msun_from_Rstruct(beta, Rs)
                    Ms.append(M); n_valid += 1
                    if lo_band <= M <= hi_band:
                        n_in += 1
    if not Ms:
        return {"ok": False, "reason": "no valid windows in sweep"}
    Ms = np.array(Ms)
    return {"ok": True, "n_combinations": n_valid,
            "M_min_Msun": float(Ms.min()), "M_max_Msun": float(Ms.max()),
            "M_median_Msun": float(np.median(Ms)),
            "fraction_in_band": float(n_in) / n_valid,
            "all_in_band": bool(n_in == n_valid),
            "band_Msun": GA_ACCEPTED_WINDOW_Msun, "origin": origin}


