def sha256_directory(root):
    """Hash determinístico (caminhos relativos + conteudo) dos fontes formais."""
    files = {}
    if not os.path.isdir(root):
        return {"aggregate": None, "files": {}}
    # v303 [A FRONTEIRA DO CONJUNTO CUSTODIADO -- o juizo de 31/08 mediu dois furos]:
    # (a) lake-manifest.json ENTRA no hash formal: ele pina as revisoes exatas das
    #     dependencias (mathlib v4.31.0 etc.) de que o fecho logico depende; um hash
    #     "dos fontes formais" que nao ve o pin nao custodia o fecho.
    # (b) ExtrairDeps.lean SAI por exclusao NOMINAL E DECLARADA: e' instrumento da
    #     BANCADA_TOE que se declara "NAO faz parte do canonico", vive so' em disco
    #     (nao esta' em _EMBEDDED_KERNEL_FILES) e entrava no hash por morar na pasta
    #     -- apaga-lo mudaria o hash formal sem mudar o kernel. "Nao ha' segundo
    #     arquivo" tinha um segundo arquivo morando dentro da pasta hasheada.
    _NOT_CANONICAL_IN_TREE = ("ExtrairDeps.lean",)
    for dirpath, _dirs, names in os.walk(root):
        if ".lake" in dirpath.replace("\\", "/").split("/"):
            continue  # ignora artefatos de build / mathlib
        for nm in sorted(names):
            if nm in _NOT_CANONICAL_IN_TREE:
                continue
            if nm.endswith(".lean") or nm in ("lakefile.toml", "lean-toolchain", "README.md", "lake-manifest.json"):
                p = os.path.join(dirpath, nm)
                rel = os.path.relpath(p, root).replace("\\", "/")
                try:
                    files[rel] = sha_file(p)
                except OSError:
                    continue
    h = hashlib.sha256()
    for rel in sorted(files):
        h.update(rel.encode("utf-8")); h.update(files[rel].encode("utf-8"))
    return {"aggregate": h.hexdigest(), "files": files}


def run_process_checked(cmd, cwd, timeout_seconds):
    """Executa um processo capturando tudo. Nunca levanta: devolve o resultado."""
    t0 = time.time()
    try:
        # encoding EXPLICITO obrigatorio: no Windows, text=True sem encoding decodifica
        # com o locale (cp1252) DENTRO da reader thread do subprocess; um unico byte
        # UTF-8 do Lean (ex.: 0x9d, terceiro byte de U+211D "R" real) mata a thread em
        # silencio e stdout volta None -> "" (bug v22, diagnosticado 11/07/2026:
        # sha256 da string vazia nas capturas do manifesto).
        pr = subprocess.run(cmd, cwd=cwd, capture_output=True, text=True,
                            encoding="utf-8", errors="replace",
                            timeout=timeout_seconds, shell=False)
        _so, _se = pr.stdout or "", pr.stderr or ""
        # triagem de captura (v23.1): hash valido de zero bytes NAO e' evidencia de
        # execucao -- a assinatura sha256("") escondeu o bug v22 por tres rodadas.
        return {"cmd": " ".join(cmd), "returncode": pr.returncode,
                "stdout": _so, "stderr": _se,
                "capture_exists": True,
                "capture_nonempty": bool(len(_so) + len(_se) > 0),
                "capture_read_error": bool(pr.stdout is None or pr.stderr is None),
                "capture_sha256": hashlib.sha256((_so + _se).encode("utf-8")).hexdigest(),
                "elapsed_seconds": time.time() - t0, "timeout": False}
    except subprocess.TimeoutExpired:
        return {"cmd": " ".join(cmd), "returncode": -1, "stdout": "", "stderr": "TIMEOUT",
                "elapsed_seconds": time.time() - t0, "timeout": True}
    except OSError as e:
        return {"cmd": " ".join(cmd), "returncode": -1, "stdout": "", "stderr": str(e),
                "elapsed_seconds": time.time() - t0, "timeout": False}


def _lean_strip_comments_and_strings(src):
    """Remove comentarios de bloco/linha e strings, para a varredura lexical AUXILIAR."""
    out, i, n = [], 0, len(src)
    while i < n:
        if src.startswith("/-", i):
            depth, i = 1, i + 2
            while i < n and depth > 0:
                if src.startswith("/-", i):
                    depth += 1; i += 2
                elif src.startswith("-/", i):
                    depth -= 1; i += 2
                else:
                    i += 1
            continue
        if src.startswith("--", i):
            while i < n and src[i] != "\n":
                i += 1
            continue
        if src[i] == '"':
            i += 1
            while i < n and src[i] != '"':
                i += 2 if src[i] == "\\" else 1
            i += 1
            continue
        out.append(src[i]); i += 1
    return "".join(out)


def _lean_source_forbidden_tokens():
    """Varredura lexical auxiliar de TODOS os fontes das bibliotecas (TGL/ + TGLExt/ +
    raizes .lean). A fonte de verdade e' #print axioms; esta rede pega o que os
    axiomas nao denunciam (native_decide -> Lean.ofReduceBool; axiom fora de
    namespace). v33.1: cobertura estendida a TGLExt apos achado do painel adversarial
    (a defesa que existia para TGL/*.lean nao havia sido estendida a nova lib)."""
    hits = []
    scan_dirs = [("TGL", os.path.join(FORMAL_DIR, "TGL")),
                 ("TGLExt", os.path.join(FORMAL_DIR, "TGLExt"))]
    scan_files = [("", os.path.join(FORMAL_DIR, "TGL.lean")),
                  ("", os.path.join(FORMAL_DIR, "TGLExt.lean"))]
    targets = []
    for label, d in scan_dirs:
        if not os.path.isdir(d):
            continue
        for nm in sorted(os.listdir(d)):
            if not nm.endswith(".lean") or nm.startswith("Probe"):
                continue  # Probe*.lean = diagnostico, fora da biblioteca
            targets.append(("%s/%s" % (label, nm), os.path.join(d, nm)))
    for label, p in scan_files:
        if os.path.exists(p):
            targets.append((os.path.basename(p), p))
    for rel, p in targets:
        try:
            src = open(p, "r", encoding="utf-8").read()
        except OSError:
            continue
        code = _lean_strip_comments_and_strings(src)
        for tok in _LEAN_FORBIDDEN_TOKENS:
            import re as _re
            if _re.search(r"\b%s\b" % _re.escape(tok), code):
                hits.append("%s:%s" % (rel, tok))
    return hits


def _find_lake():
    """Resolve o binario `lake`: TGL_LAKE (env) -> PATH -> ~/.elan/bin (elan nem sempre esta
    no PATH do processo que chama o Python). Devolve None se nao existir."""
    envp = os.environ.get("TGL_LAKE")
    if envp and os.path.exists(envp):
        return envp
    w = shutil.which("lake")
    if w:
        return w
    home = os.path.expanduser("~")
    for cand in (os.path.join(home, ".elan", "bin", "lake.exe"),
                 os.path.join(home, ".elan", "bin", "lake")):
        if os.path.exists(cand):
            return cand
    return None


