    groups = [np.where(theta_v <= q[0])[0], np.where((theta_v > q[0]) & (theta_v <= q[1]))[0],
              np.where((theta_v > q[1]) & (theta_v <= q[2]))[0], np.where(theta_v > q[2])[0]]
    bins_x = np.array(frozen["bins_x"])
    xc = 0.5 * (bins_x[:-1] + bins_x[1:])
