    a2, b2 = np.kron(E01, np.eye(2)), np.kron(E10, np.eye(2))
    r2 = np.trace(rho2 @ a2 @ b2) / np.trace(rho2 @ b2 @ a2)
    resid_pers = abs(float(np.real(r2 - r1)))
