    def _rhat(cat, xc, seed, ra_side=None):
        rng = np.random.default_rng(seed)
        M = 20000
        ci = rng.integers(0, len(occ_list), M)
        Rr = cat[:, 3][rng.integers(0, cat.shape[0], M)]
