        b1 = env * np.cos(ph); b2 = env * np.sin(ph); s1 = np.zeros_like(b1); s2 = np.zeros_like(b2)
        s1[:, lag:] = b1[:, :n - lag]; s2[:, lag:] = b2[:, :n - lag]
        B = np.stack([b1, b2, s1, s2], axis=1); Gm = np.einsum("kin,kjn->kij", B, B)
