    w2 = np.kron([1.0 / 3, 2.0 / 3], [1.0 / 3, 2.0 / 3])   # [1/9, 2/9, 2/9, 4/9]
    rho = np.diag(w2).astype(complex)
    lw = np.log(w2)
    omega = lambda a: complex(np.trace(rho @ a))
    # o REFERENTE, medido DE VERDADE (correcao do critico de 01/09: o check antigo
