    s.append(r"\usepackage{amsmath,amssymb,amsthm}\usepackage[hidelinks]{hyperref}")
    s.append(r"\usepackage{parskip}\usepackage{booktabs}\usepackage{xcolor}")
    s.append(r"\usepackage{graphicx}\usepackage{longtable}")
