    _hd = core["half_nat_continuous_corner_density"]; _hn = _hd["natural_units"]; _hv = _hd["values_SI"]
    s.append(r"\subsection*{From the Half-Nat to the inscription density \textsf{[DER + NORM + CONDITIONAL]}}")
