            comparison = {"reference_Mpc": Dref, "reference_sigma": sref,
                          "z_TGL": z_tgl, "z_planck_control": z_pl,
                          "residual_TGL_Mpc": D_E2_med - Dref,
                          "residual_planck_Mpc": D_C1_med - Dref}
            azt, azp = abs(z_tgl), abs(z_pl)
