def _jc_beta():
    """beta_TGL em runtime (jamais literal)."""
    return SEALED_CODATA_ALPHA * math.sqrt(math.e)


def _jc_fisher_survival(X, k):
    """P(chi2 com 2k graus >= X) em forma fechada (graus pares), estavel para caudas pequenas."""
    if k <= 0:
        return 1.0
    h = X / 2.0
    term = 1.0; acc = 1.0
    for j in range(1, k):
        term *= h / j; acc += term
    return float(min(1.0, math.exp(-h) * acc))


def _jc_channel_p(ch, W, n_forms_override=None):
    """p de coincidencia de UM canal sob o nulo log-uniforme de largura W (em ln) em torno da previsao.
    p = min(1, 2 r / W), r = max(|ln(obs/pred)|, sigma/|obs|); obs <= 0, sem sigma ou afastamento >= 100% => p = 1 (nao ha coincidencia a pagar).
    Correcao de tentativas: p' = 1 - (1 - p)^N."""
    obs, sig, pred = ch.get("obs"), ch.get("sigma"), ch.get("pred")
    if not all(isinstance(v, (int, float)) for v in (obs, sig, pred)) or pred <= 0 or obs <= 0 or sig <= 0:
        p = 1.0
    else:
        r = max(abs(math.log(obs / pred)), sig / abs(obs))
        p = 1.0 if abs(obs - pred) >= pred else min(1.0, 2.0 * r / W)
    N = int(n_forms_override if n_forms_override is not None else ch.get("n_forms", 1))
    return float(1.0 - (1.0 - p) ** max(1, N)) if p < 1.0 else 1.0


def tgl_joint_coincidence_boolean(channels, threshold=1e-30, z_max=3.0, W=None, n_forms_override=None):
    """A FUNCAO BOOLEANA DE ENTRADA E SAIDA (ordem do operador, 14/09/2026).
    ENTRADA: lista de canais {obs, sigma, pred, n_forms, admissible}; limiar da probabilidade conjunta; z maximo de consistencia.
    SAIDA: True  <=> ha pelo menos um canal admissivel, a probabilidade conjunta de coincidencia (Fisher sobre TODOS os admissiveis) fica ABAIXO do
                     limiar E nenhum canal admissivel contradiz a previsao alem de z_max;
           False <=> qualquer uma das tres condicoes falha.
    Pode sair False: e' isso que a torna medida (um teste que nao pode falhar nao e' medida)."""
    W = W if W is not None else math.log(100.0)
    adm = [c for c in channels if c.get("admissible")]
    if not adm:
        return False
    ps = [_jc_channel_p(c, W, n_forms_override) for c in adm]
    X = -2.0 * sum(math.log(max(p, 1e-300)) for p in ps)
    p_joint = _jc_fisher_survival(X, len(ps))
    zs = [abs((c["obs"] - c["pred"]) / c["sigma"]) for c in adm if isinstance(c.get("sigma"), (int, float)) and c["sigma"] > 0 and isinstance(c.get("obs"), (int, float))]
    return bool(p_joint < threshold and (max(zs) if zs else 0.0) < z_max)


def _jc_measure(channels, threshold, z_max, W, n_forms_override=None):
    adm = [c for c in channels if c.get("admissible")]
    rows = []
    for c in adm:
        z = ((c["obs"] - c["pred"]) / c["sigma"]) if (isinstance(c.get("sigma"), (int, float)) and c["sigma"] > 0) else None
        rows.append({"id": c["id"], "p_channel": _jc_channel_p(c, W, n_forms_override), "z_vs_prediction": z})
    X = -2.0 * sum(math.log(max(r["p_channel"], 1e-300)) for r in rows)
    pj = _jc_fisher_survival(X, len(rows)) if rows else None
    zmax = max((abs(r["z_vs_prediction"]) for r in rows if r["z_vs_prediction"] is not None), default=None)
    return {"k_admissible": len(rows), "per_channel": rows, "fisher_X": X, "p_joint": pj, "max_abs_z": zmax,
            "boolean": tgl_joint_coincidence_boolean(channels, threshold, z_max, W, n_forms_override)}


